INSERT INTO `sys_i18n` VALUES (5400, 'alert.config.expr.comment', 'en', 'alert.config.expr.comment', 'Operation expression (required) Example: 100-(avg(irate(node_cpu_seconds_total)[5m])) by(instance)* 100)', '', '2021-12-06 19:36:37', 1);
