INSERT INTO `sys_i18n` VALUES (5418, 'alert.notify.comment', 'en', 'alert.notify.comment', 'Alarm notification method. When the receiver is not empty, it is required. Multiple use commas to separate Example: email / emai', '', '2021-12-06 19:41:19', 1);
