INSERT INTO `sys_i18n` VALUES (5426, 'alert.config.schedDays.comment', 'en', 'alert.config.schedDays.comment', 'schedule open day (week) Timer is turned on, default: 1,2,3,4,5,6,7 multiple comma separation Example: 1,2,3,4,6', '', '2021-12-06 19:43:15', 1);
